async function api(path:string,method='GET',body?:any){const r=await fetch('/api/'+path,{method,signal:AbortSignal.timeout(15000),headers:{'Content-Type':'application/json','x-campus-session':typeof window!=='undefined'?(sessionStorage.getItem('cc-role-session')||''):''},...(body?{body:JSON.stringify(body)}:{})});const d:any=await r.json();if(!r.ok)throw Error(d.error||'Request failed. Please try again.');return d;}
function Brand(){return <div className="brand"><span className="brandmark"><GraduationCap size={24}/></span><span>campus<span className="brandlight">connect</span><small>BETTER CAMPUS. TOGETHER.</small></span></div>}
