async function refresh(){try{const d=await api('tickets');setTickets(d.tickets);setAi(d.ai)}catch(e:any){setError(e.message)}finally{setLoading(false)}}
useEffect(()=>{api('session').then(d=>{setUser(d.user);setAi(d.ai)}).catch(e=>setError(e.message)).finally(()=>setBoot(false))},[]);
useEffect(()=>{if(!user)return;setLoading(true);refresh();try{const d=localStorage.getItem('cc-draft-'+user.id);setForm(d?{...blank,...JSON.parse(d),photo:''}:blank)}catch{}const id=setInterval(refresh,user.role==='student'?5000:1000);const onFocus=()=>refresh();window.addEventListener('focus',onFocus);return()=>{clearInterval(id);window.removeEventListener('focus',onFocus)}},[user?.id]);
useEffect(()=>{if(!user||!['staff','faculty'].includes(user.role))return;const fires=tickets.filter(t=>t.priority==='fire'&&t.status!=='Resolved'&&!sessionStorage.getItem('cc-fire-seen-'+t.id));if(fires.length){fires.forEach(t=>sessionStorage.setItem('cc-fire-seen-'+t.id,'1'));setFireAlertId(fires[0].id)}},[tickets,user?.role]);
useEffect(()=>{if(!fireAlertId||!user||!['staff','faculty'].includes(user.role)){setFireAlertActive(false);return}setFireAlertActive(true);const timer=setTimeout(()=>setFireAlertActive(false),10000);return()=>clearTimeout(timer)},[fireAlertId,user?.role]);
useEffect(()=>{if(!user||typeof BroadcastChannel==='undefined')return;const channel=new BroadcastChannel('campus-connect-tickets');channel.onmessage=()=>refresh();return()=>channel.close()},[user?.id]);
function notifyDashboards(){if(typeof BroadcastChannel==='undefined')return;const channel=new BroadcastChannel('campus-connect-tickets');channel.postMessage('updated');channel.close()}

useEffect(()=>{if(user)try{localStorage.setItem('cc-draft-'+user.id,JSON.stringify({...form,photo:''}));}catch{}},[form]);
