useEffect(()=>{if(!modal&&!selected&&!fireOpen)return;const before=document.activeElement as HTMLElement;const dialog=document.querySelector('[role="dialog"]') as HTMLElement;const first=dialog?.querySelector('button,input,textarea,select') as HTMLElement;first?.focus();const trap=(e:KeyboardEvent)=>{if(e.key!=='Tab'||!dialog)return;const all=Array.from(dialog.querySelectorAll('button:not(:disabled),input,textarea,select,a[href]')).filter((el:any)=>el.offsetParent!==null) as HTMLElement[];if(!all.length)return;if(e.shiftKey&&document.activeElement===all[0]){e.preventDefault();all.at(-1)?.focus()}else if(!e.shiftKey&&document.activeElement===all.at(-1)){e.preventDefault();all[0].focus()}};document.addEventListener('keydown',trap);const old=document.body.style.overflow;document.body.style.overflow='hidden';return()=>{document.removeEventListener('keydown',trap);document.body.style.overflow=old;before?.focus()}},[modal,selected?.id,fireOpen]);
async function signIn(e:React.FormEvent){e.preventDefault();setBusy(true);setError('');try{const d=await api('session','POST',{...login,role:loginRole});sessionStorage.setItem('cc-role-session',d.token);setUser(d.user);setView('Overview');setTickets([]);setFilter('All');setQuery('');setShowDemo(false);setLogin({roll:'',email:'',staffId:'',phone:'',key:''})}catch(e:any){setError(e.message)}finally{setBusy(false)}}
