async function sendFireAlert(payload:FirePayload){if(fireSubmitting.current)return;fireSubmitting.current=true;setBusy(true);setError('');try{const t=await api('tickets','POST',{...blank,title:'Fire reported on campus',category:'Electricity',priority:'fire',location:payload.location.trim()||'Location not supplied — staff must confirm',description:payload.description.trim().length>=10?payload.description.trim():'Fire reported on campus. Staff must confirm the location and coordinate the response.'+(payload.description.trim()?' Student note: '+payload.description.trim():''),mapCoordinates:payload.mapCoordinates});notifyDashboards();setFireOpen(false);setToast('Fire alert sent to the staff dashboards.');await refresh();openTicket(t)}catch(e:any){setError(e.message)}finally{setBusy(false);fireSubmitting.current=false}}

function captureLocation(){if(!navigator.geolocation){setError('Live location is not available in this browser.');return}setError('');navigator.geolocation.getCurrentPosition(pos=>setForm(f=>({...f,mapCoordinates:`${pos.coords.latitude.toFixed(6)},${pos.coords.longitude.toFixed(6)}`})),()=>setError('Location was not shared. You can still enter a building or room.'),{enableHighAccuracy:true,timeout:10000,maximumAge:30000})}

function openTicket(t:Ticket){setSelected(t);setNote('');setAssignee(t.assigneeId||'');setLinked(t.linkedTo||'');setError('');setAction(user?.role==='staff'&&!t.assigneeId&&t.status==='Submitted'?'claim':user?.role==='faculty'&&t.status==='Submitted'?'assign':user?.role==='staff'&&t.status==='Assigned'?'start':user?.role==='staff'&&t.status==='In progress'?'complete':t.status==='Awaiting verification'&&user?.role==='faculty'?'verify':user?.role==='student'&&t.status!=='Resolved'?'remind':'note')}
async function analyze(){if(form.description.trim().length<10){setError('Describe the issue in at least 10 characters.');return;}setBusy(true);setError('');try{const a=await api('analyze','POST',form);setAnalysis(a);setForm(f=>({...f,title:a.title||f.title,category:a.category||f.category}));setStep(2)}catch(e:any){setError(e.message)}finally{setBusy(false)}}
async function submit(){setBusy(true);setError('');try{const t=await api('tickets','POST',form);notifyDashboards();setModal(false);setForm(blank);setToast('Report submitted — '+shortId(t.id));await refresh();openTicket(t)}catch(e:any){setError(e.message)}finally{setBusy(false)}}
async function save(nextAction=action){if(!selected)return;setBusy(true);setError('');try{const t=await api('tickets','PATCH',{id:selected.id,version:selected.version,action:nextAction,note,assigneeId:assignee,linkedTo:linked});notifyDashboards();openTicket(t);setToast('Update saved. The progress timeline is up to date.');await refresh()}catch(e:any){if(e.message.includes('changed')){try{const d=await api('tickets');setTickets(d.tickets);const latest=d.tickets.find((t:Ticket)=>t.id===selected.id);if(latest){setSelected(latest);setAction(allowed(latest)[0]||'note')}}catch{}}setError(e.message)}finally{setBusy(false)}}
async function upload(file?:File){if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>8*1024*1024){setError('Use a JPEG, PNG or WebP under 8 MB.');return;}setBusy(true);try{const bitmap=await createImageBitmap(file);const canvas=document.createElement('canvas');const scale=Math.min(1,1100/Math.max(bitmap.width,bitmap.height));canvas.width=bitmap.width*scale;canvas.height=bitmap.height*scale;canvas.getContext('2d')!.drawImage(bitmap,0,0,canvas.width,canvas.height);const photo=canvas.toDataURL('image/jpeg',.7);bitmap.close();if(photo.length>600000)throw Error('This photo is too detailed. Try a smaller image.');setForm(f=>({...f,photo}));setError('')}catch(e:any){setError(e.message||'Could not read this photo.')}finally{setBusy(false)}}
