function allowed(t:Ticket){if(role==='student'&&!t.isMine)return [];const emergency=['emergency','fire'].includes(t.priority||'')&&t.status!=='Resolved'&&!t.acknowledgedAt?['acknowledge']:[];if(role==='staff'&&t.priority==='fire'&&t.assigneeId!==user?.id)return emergency;if(role==='student')return t.status==='Awaiting verification'?['remind','reopen']:t.status==='Resolved'?['reopen']:['remind'];if(role==='staff')return !t.assigneeId&&t.status==='Submitted'?['claim',...emergency]:[...emergency,...(t.status==='Assigned'?['start','note']:t.status==='In progress'?['complete','note']:['note'])];return [...emergency,...(['Submitted','Assigned','In progress'].includes(t.status)?['assign']:[]),...(t.status==='Awaiting verification'?['verify','reopen']:t.status==='Resolved'?['reopen']:[]),'link','note'];}

